sources.cmd:
cd {{cwd}} 2>/dev/null || { echo @@nodir; exit 0; }
g='git --no-optional-locks -c core.quotePath=false -c color.ui=false'
cd "$($g rev-parse --show-toplevel 2>/dev/null)" 2>/dev/null || { echo @@bad; exit 0; }
printf '%s' "$HATCH_ARG" | { IFS=$(printf '\t') read -r m r p f
t=$(mktemp) || exit 0
case "$m" in
  unstaged) $g diff --no-ext-diff --no-textconv -- "$p";;
  staged) $g diff --cached -M --no-ext-diff --no-textconv -- ${f:+"$f"} "$p";;
  untracked) if [ -d "$p" ]; then echo @@list; $g ls-files --others --exclude-standard -- "$p" | head -200; else $g diff --no-index --no-ext-diff --no-textconv -- /dev/null "$p"; fi;;
  commit) case "$r" in ''|*[!0-9a-f]*) echo @@bad;; *) $g show --format= -m --first-parent -M --no-ext-diff --no-textconv "$r" -- ${f:+"$f"} "$p";; esac;;
  *) echo @@bad;;
esac | head -c 40001 >"$t"
[ "$(wc -c <"$t")" -gt 40000 ] && echo @@trunc
head -c 40000 "$t"; rm -f "$t"; }

cd {{cwd}} 2>/dev/null || { echo @@nodir; exit 0; }
top=$(git rev-parse --show-toplevel 2>/dev/null) || { echo @@norepo; exit 0; }
command -v claude >/dev/null 2>&1 || { echo @@noclaude; exit 0; }
f="${TMPDIR:-/tmp}/hatch-commit-$(printf %s "$top" | cksum | cut -d' ' -f1)"
if [ -f "$f.s" ]; then read -r st pid <"$f.s"; if [ "$st" = running ] && kill -0 "$pid" 2>/dev/null; then echo @@running; exit 0; fi; fi
rm -f "$f.s" "$f.err"
nohup /bin/sh -c 'cd "$1" || exit 1; echo "running $$" >"$2.s"; out=$(claude -p "Commit the current state of the git repository at $1 (work there). Look at git status and git diff, decide which changes belong together, stage them, and write a commit message in the style of the recent commits (git log -n 10). Before committing, check the staged diff for private information (secrets, tokens, hostnames, usernames, emails, absolute home paths, private project names); if the repository is public, leave such content out or stop and say so. Do not push, do not amend or rewrite history, do not switch branches. Reply with one short line saying what you committed." --permission-mode auto </dev/null 2>"$2.err"); rc=$?; { echo "done $rc $(date +%s)"; printf %s "$out" | tail -n 1; tail -n 1 "$2.err"; } >"$2.t"; mv "$2.t" "$2.s"' sh "$top" "$f" >/dev/null 2>&1 </dev/null &
echo @@started
